// DID Key Identity — offline `did:key` (Ed25519) parsing and signature verification
// (didkey.py), plus its one caller, app.py's `_signer` (app.py:1147-1169), which turns a
// raw HTTP (did, sig, nonce, canonical-message) tuple into a verified signer identity or a
// mapped refusal (400 vs 403).
//
// Every operation here is a pure QUERY: no operation persists anything across calls (there
// is no module-level state in didkey.py at all). The state this spec tracks exists only so
// the oracle has something to log a transition against and so observations/properties can
// read "what did the most recent call of each kind decide" — it is not state the real
// system keeps. Each action always fires (there is no scenario where the real code refuses
// to even attempt verification); the only actual guard in this spec is `abbreviate`'s,
// which encodes a documented-but-code-unenforced precondition (see below).
//
// Quint has no string manipulation (no slicing, no base58/base64 decode, no regex), so
// `public_key`'s byte-level parsing (didkey.py:45-68) and `verify`'s signature-encoding
// regex (didkey.py:97-99) are modeled by SHAPE, not by literal decoding: each symbolic DID
// / signature string in the domain below is pre-tagged with the DidShape/SigShape category
// its real bytes would produce, mirroring the actual guard-chain ORDER and OUTCOME
// (DidError vs SignatureError) rather than the byte math. This is the same technique
// quint-specs/rooms.qnt uses for room names.
//
// The Ed25519 cryptographic check itself (didkey.py:100-103) cannot be decided from any
// data in this model — a real signature's validity depends on private-key material this
// spec never sees — so it is modeled as an independent nondet choice (SigAuthenticity),
// exactly the "attacker cannot compute forgery from public data" property the real code
// gets from Ed25519's unforgeability. No app.py test logs the `sig` argument either
// (app.py:1224, 1334 — a fresh key is generated per test run), so this dimension is
// always an unpinned, bounded-search wildcard during replay — a 2-element domain, cheap.
//
// Explicitly OUT of scope: nonce ORDERING / replay rejection. `_signer` only checks nonce
// SHAPE (1-19 digits, app.py:1157-1158); whether a given nonce is a replay of one already
// seen for that DID in that room is decided downstream, by store.py/app.py's
// `_last_nonce`/`_burn_nonce` machinery, which is already modeled by the `rooms` and
// `notes-store` components (their `nonce_strictly_increasing` property). Modeling it again
// here would duplicate, not ground, that guarantee.
module did_key_identity {
  import basicSpells.* from "./spells/basicSpells"

  // --------------------------------------------------------------------- domains

  // The four DidError-triggering guard clauses in public_key() (didkey.py:55-68), plus
  // success. Each has exactly one representative in DIDS below.
  type DidShape =
    | ValidDidKey          // every check passes — public_key() returns the raw key bytes
    | WrongPrefixOrType     // not isinstance(str) or not did.startswith("did:key:") (didkey.py:57)
    | WrongMultibaseShape   // len(mb) != 48 or not mb.startswith("z") (didkey.py:60)
    | NotBase58Chars        // a character outside the base58btc alphabet (didkey.py:49-50)
    | WrongDecodedShape     // decoded length != 34, or wrong multicodec prefix (didkey.py:66)

  // The signature-encoding regex (didkey.py:97-98): exactly 86 base64url characters.
  type SigShape = ValidSigEncoding | BadSigEncoding

  // Whether a well-formed-looking signature is genuinely `did`'s Ed25519 signature over
  // the exact message presented — undecidable from any other field in this model, by
  // design (see header comment).
  type SigAuthenticity = Genuine | Forged

  // _signer's own check (app.py:1157-1158): NONCE_RE = [0-9]{1,19}.
  type NonceShape = ValidNonceShape | BadNonceShape

  type VerifyOutcome = VerifyAccepted | VerifyDidError | VerifySignatureError
  type SignerOutcome = SignerAccepted | SignerNonceRejected | SignerDidRejected | SignerSignatureRejected

  pure val DIDS: Set[str] = Set(
    "did:key:zAlice", "did:key:zBob",   // ValidDidKey
    "missing-prefix",                    // WrongPrefixOrType
    "did:key:zBadMultibaseLen",          // WrongMultibaseShape
    "did:key:zBadCharI0Ol",              // NotBase58Chars
    "did:key:zBadDecoded"                // WrongDecodedShape
  )

  pure val SIGS: Set[str] = Set("sigWellFormed", "sigBadEncoding")
  pure val SIG_AUTHS: Set[SigAuthenticity] = Set(Genuine, Forged)
  pure val MESSAGES: Set[str] = Set("msgA", "msgB")
  // 1-19 digits (valid, including the 19-digit boundary) vs empty/non-digit/negative (bad).
  pure val NONCES: Set[str] = Set("1", "999999999999999999", "", "12a3")

  // --------------------------------------------------------------------- pure functions

  pure def didShapeOf(did: str): DidShape =
    if (did == "did:key:zAlice" or did == "did:key:zBob") ValidDidKey
    else if (did == "missing-prefix") WrongPrefixOrType
    else if (did == "did:key:zBadMultibaseLen") WrongMultibaseShape
    else if (did == "did:key:zBadCharI0Ol") NotBase58Chars
    else if (did == "did:key:zBadDecoded") WrongDecodedShape
    else WrongPrefixOrType

  pure def sigShapeOf(sig: str): SigShape =
    if (sig == "sigBadEncoding") BadSigEncoding else ValidSigEncoding

  pure def nonceShapeOf(nonce: str): NonceShape =
    if (nonce == "1" or nonce == "999999999999999999") ValidNonceShape else BadNonceShape

  // public_key() succeeding is exactly "the DID has ValidDidKey shape" (didkey.py:55-68).
  pure def publicKeyOk(did: str): bool = didShapeOf(did) == ValidDidKey

  // is_did() is literally try: public_key(value); except (DidError, TypeError): False
  // (didkey.py:71-78) — the same check, wrapped.
  pure def isDidPure(value: str): bool = publicKeyOk(value)

  // verify() (didkey.py:89-103): public_key(did) is called FIRST, so a bad DID always wins
  // over a bad signature; a bad signature ENCODING is also a DidError (didkey.py:97-98),
  // not a SignatureError — only a well-formed-everything signature that fails the actual
  // Ed25519 check reaches SignatureError.
  pure def verifyOutcome(did: str, sig: str, auth: SigAuthenticity): VerifyOutcome =
    if (didShapeOf(did) != ValidDidKey) VerifyDidError
    else if (sigShapeOf(sig) != ValidSigEncoding) VerifyDidError
    else if (auth != Genuine) VerifySignatureError
    else VerifyAccepted

  // _signer() (app.py:1147-1169): nonce shape is checked before verify() is even called.
  pure def signerOutcome(nonce: str, did: str, sig: str, auth: SigAuthenticity): SignerOutcome =
    if (nonceShapeOf(nonce) != ValidNonceShape) SignerNonceRejected
    else match verifyOutcome(did, sig, auth) {
      | VerifyDidError => SignerDidRejected
      | VerifySignatureError => SignerSignatureRejected
      | VerifyAccepted => SignerAccepted
    }

  // --------------------------------------------------------------------- state

  type VerifyCall = { outcome: VerifyOutcome, did: str, sig: str }
  type SignerCall = { outcome: SignerOutcome, nonce: str, did: str, identity: str }
  type IsDidCall = { value: str, result: bool }

  type State = {
    publicKeyLast: Option[DidShape],
    isDidLast: Option[IsDidCall],
    abbreviateLast: Option[str],
    verifyLast: Option[VerifyCall],
    signerLast: Option[SignerCall],
  }

  var st: State

  action init: bool = all {
    st' = {
      publicKeyLast: None,
      isDidLast: None,
      abbreviateLast: None,
      verifyLast: None,
      signerLast: None,
    },
  }

  // public_key(did) — didkey.py:55. Also the standalone defense-in-depth revalidation
  // store.py:1156 (_write_record) performs before persisting a signed record.
  action public_key(did: str): bool = all {
    st' = { ...st, publicKeyLast: Some(didShapeOf(did)) },
  }

  // is_did(value) — didkey.py:71. A pure shape predicate, never proof of ownership; also
  // used on plain nicknames (app.py:107,111), not only on things claiming to be DIDs.
  action is_did(value: str): bool = all {
    st' = { ...st, isDidLast: Some({ value: value, result: isDidPure(value) }) },
  }

  // abbreviate(did) — didkey.py:81. The docstring/every call site (app.py:610,1089,1622)
  // trusts the caller already checked is_did(did) first; the function body itself performs
  // NO check. That is a documented-but-unenforced precondition (component-map
  // adversarySurface row 1) — modeled here as a guard even though didkey.py doesn't
  // enforce it: a real call reaching this action with a non-ValidDidKey `did` is a
  // contract violation the oracle can flag, not a crash the model needs to fake.
  action abbreviate(did: str): bool = all {
    didShapeOf(did) == ValidDidKey,
    st' = { ...st, abbreviateLast: Some(did) },
  }

  // verify(did, signature, message) — didkey.py:89.
  action verify(did: str, sig: str, auth: SigAuthenticity, message: str): bool = all {
    st' = { ...st, verifyLast: Some({ outcome: verifyOutcome(did, sig, auth), did: did, sig: sig }) },
  }

  // _signer(did, sig, nonce, canonical) — app.py:1147. The one caller of verify(); on
  // success it returns exactly the `did` it verified (app.py:1169), which becomes the
  // stored record's `from` field for both the room and note signed-write lanes.
  action signer(nonce: str, did: str, sig: str, auth: SigAuthenticity, message: str): bool = {
    val outcome = signerOutcome(nonce, did, sig, auth)
    all {
      st' = { ...st, signerLast: Some({
          outcome: outcome,
          nonce: nonce,
          did: did,
          identity: if (outcome == SignerAccepted) did else "",
        }) },
    }
  }

  action step = any {
    nondet did = DIDS.oneOf()
    public_key(did),

    nondet value = DIDS.oneOf()
    is_did(value),

    nondet did = DIDS.oneOf()
    abbreviate(did),

    { nondet did = DIDS.oneOf()
      nondet sig = SIGS.oneOf()
      nondet auth = SIG_AUTHS.oneOf()
      nondet message = MESSAGES.oneOf()
      verify(did, sig, auth, message) },

    { nondet nonce = NONCES.oneOf()
      nondet did = DIDS.oneOf()
      nondet sig = SIGS.oneOf()
      nondet auth = SIG_AUTHS.oneOf()
      nondet message = MESSAGES.oneOf()
      signer(nonce, did, sig, auth, message) },
  }

  // --------------------------------------------------------------------- properties

  /// A malformed did:key or a malformed signature encoding is always reported as the
  /// identity's own problem (DidError, HTTP 400 — app.py:1161-1162) — verify() never
  /// blames the signature itself (SignatureError, HTTP 403) unless the DID parsed AND the
  /// signature encoding was well-formed. A caller debugging a 403 can therefore always
  /// trust their DID string and encoding were accepted, and the problem is the signature
  /// value itself.
  val verify_did_error_precedes_signature_error: bool =
    match st.verifyLast {
      | Some(call) => call.outcome == VerifySignatureError implies
          (didShapeOf(call.did) == ValidDidKey and sigShapeOf(call.sig) == ValidSigEncoding)
      | None => true
    }

  /// On a successful signed write, the identity `_signer` returns is exactly the did:key
  /// whose signature was checked — never blank, never substituted for a different DID. A
  /// stored message's "from" field can therefore never be misattributed to a signer other
  /// than the one that actually produced the signature.
  val signer_returns_the_verified_identity: bool =
    match st.signerLast {
      | Some(call) => call.outcome == SignerAccepted implies call.identity == call.did
      | None => true
    }

  /// is_did() and public_key() never disagree about which strings are valid did:keys —
  /// is_did is documented as exactly the same shape check public_key performs, just
  /// reduced to a boolean. A caller who gates a later public_key()-based operation on
  /// is_did() cannot be let through on a DID public_key() would then reject.
  val is_did_agrees_with_public_key: bool =
    match st.isDidLast {
      | Some(call) => call.result == (didShapeOf(call.value) == ValidDidKey)
      | None => true
    }

  // --------------------------------------------------------------------- observations

  /// public_key() successfully parsed a well-formed did:key into raw key bytes.
  val did_parsed_ok: bool =
    match st.publicKeyLast { | Some(shape) => shape == ValidDidKey | None => false }

  /// public_key() rejected a malformed did:key (any of the four DidError categories).
  val did_parse_rejected: bool =
    match st.publicKeyLast { | Some(shape) => shape != ValidDidKey | None => false }

  /// verify() accepted a (did, signature, message) triple end to end.
  val verify_accepted: bool =
    match st.verifyLast { | Some(call) => call.outcome == VerifyAccepted | None => false }

  /// verify() rejected because the DID or the signature encoding was malformed (the
  /// 400-class refusal).
  val verify_did_error: bool =
    match st.verifyLast { | Some(call) => call.outcome == VerifyDidError | None => false }

  /// verify() rejected a well-formed DID and encoding whose signature does not actually
  /// check out (the 403-class refusal).
  val verify_signature_error: bool =
    match st.verifyLast { | Some(call) => call.outcome == VerifySignatureError | None => false }

  /// abbreviate() ran on an already-verified did:key, as its (unenforced) contract requires.
  val abbreviate_ran_on_valid_did: bool =
    st.abbreviateLast != None

  /// _signer() accepted a full signed write end to end (nonce shape + verify()).
  val signer_accepted: bool =
    match st.signerLast { | Some(call) => call.outcome == SignerAccepted | None => false }

  /// _signer() rejected a write before even checking the signature, because the nonce
  /// itself was not 1-19 digits.
  val signer_rejected_bad_nonce: bool =
    match st.signerLast { | Some(call) => call.outcome == SignerNonceRejected | None => false }

  /// _signer() rejected a write whose DID was malformed (propagated from verify()).
  val signer_rejected_did: bool =
    match st.signerLast { | Some(call) => call.outcome == SignerDidRejected | None => false }

  /// _signer() rejected a write whose signature did not check out (propagated from verify()).
  val signer_rejected_signature: bool =
    match st.signerLast { | Some(call) => call.outcome == SignerSignatureRejected | None => false }
}

